// Custom Worker entry: the OpenNext handler plus a Cron Trigger that calls the
// same scheduled-publish route Vercel Cron used to hit.
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = {
  CRON_SECRET?: string;
  NEXT_PUBLIC_SITE_URL?: string;
  [key: string]: unknown;
};

type Context = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };

const worker = {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: Context) {
    if (!env.CRON_SECRET) {
      console.error("Scheduled publish skipped: CRON_SECRET is not set");
      return;
    }
    const base = env.NEXT_PUBLIC_SITE_URL || "https://localhost";
    const request = new Request(new URL("/api/cron/publish", base), {
      method: "GET",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      (async () => {
        const response: Response = await handler.fetch(request, env, ctx);
        if (!response.ok) console.error("Scheduled publish failed", response.status, await response.text());
      })(),
    );
  },
};

export default worker;
